var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobCompletionResultPanel panel = null;
foreach (var r in roots) {
    panel = r.GetComponentInChildren<Sim.Jobs.JobCompletionResultPanel>(true);
    if (panel != null) break;
}
var card = panel.transform.Find("Modal/Card");
Debug.Log("Card children=" + card.childCount);
for (int i = 0; i < card.childCount; i++) {
    var c = card.GetChild(i);
    Debug.Log("  [" + i + "] " + c.name + " childCount=" + c.childCount);
    for (int j = 0; j < c.childCount; j++) Debug.Log("     - " + c.GetChild(j).name);
}
var views = panel.GetComponentsInChildren<Sim.Jobs.JobResultView>(true);
Debug.Log("Views found: " + views.Length);
foreach (var v in views) Debug.Log("  - " + v.GetType().Name + " variant=" + v.Variant);
